/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG CSE calculation (with CCR)
/// </summary>
final class METTMSShipmentItemGroupUOM_CSECCR extends METTMSShipmentItemGroupUOM_CSE
{
}

Method.Source:
/// <summary>
/// Initialise class parameters
/// </summary>
/// <param name = "_processLinesTmp">Temp table raw data</param>
/// <param name = "_lineTmpSum">Temp table summed by LineCommodity</param>
/// <param name = "_tmsShipmentOrderIdentifier">SO finalisation shipment id</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_ccrHelper">CCR helper class instance</param>
/// <param name = "_isKegItem">SO finalisation shipment id</param>
void initParameters(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp,
                    METTMSEngineSalesOrderProccessLinesTmp _lineTmpSum,
                    METTMSShipmentOrderIdentifier          _tmsShipmentOrderIdentifier,
                    InventLocationId                       _headerInventLocationId,
                    boolean                                _isToteCustomer,
                    METTMSCCRTableHelper                   _ccrHelper = null,
                    boolean                                _isKegItem = false)
{
    super(_processLinesTmp, _lineTmpSum, _tmsShipmentOrderIdentifier, _headerInventLocationId, _isToteCustomer, _ccrHelper, _isKegItem);

    this.initCCRParameters();
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    METQty ret;

    // Keg “PAL” TSIGs are created under the same conditions as described in the same section in the CB624 FSD
    // and with the same logic. Kegs will not have CCR data.
    // DoesCustUseTotes = Y same calc as non CCR
    // calc is the same except when DoesCustUseTotes = N
    ret = super(_quantity);

    if (!isToteCustomer)
    {
        // Add Sum of (CCRWhs_CaseVolume * Count(CCR_RepackContainersByCommodity) for this CCR_LineCommodity) from all supplying warehouses.
        ret += sumRepackContainersByCommodityCaseVolumeCCR;
    }

    return ret;
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <returns>TSIG quantity</returns>
METQty quantity()
{
    // Same calc as METTMSShipmentItemGroupUOM_CSE
    METQty ret = super();

    // The only difference is when customer does not use Totes, need to add CCR_RepackContainersByCommodity
    if (!isToteCustomer)
    {
        ret += sumRepackContainersByCommodityQtyCCR;
    }

    return ret;
}
